use xiom.io;
interface Identifiable {
  fn id(&self) -> Int;
}

interface Summarizable {
  fn summary(&self) -> Str;
}

type Record {
  record_id: Int;
  data: Str;
}

fn Record.id(&self) -> Int {
  self.record_id
}

fn Record.summary(&self) -> Str {
  self.data.clone()
}

fn archive[T: Identifiable + Summarizable](item: &T) {
  io.println(item.id().to_str());
  io.println(item.summary());
}

fn main() -> Int {
  let r = Record{ record_id: 1, data: "Important note" };
  archive(&r);
  return 0;
}
